schema_evidence.quote:
CREATE TABLE vehicle_type_dict (
    type_code VARCHAR(20) PRIMARY KEY COMMENT '类型代码',
    type_name VARCHAR(50) NOT NULL COMMENT '类型名称（客车/货车/危化品车等）',
    category VARCHAR(20) COMMENT '大类'
) ENGINE=InnoDB COMMENT='车辆类型字典';

CREATE TABLE license_type_dict (
    license_code VARCHAR(5) PRIMARY KEY COMMENT '驾照代码',
    license_name VARCHAR(50) NOT NULL COMMENT '驾照名称'
) ENGINE=InnoDB COMMENT='驾照类型字典';

CREATE TABLE dict_registration_type (
    type_code VARCHAR(20) PRIMARY KEY COMMENT '注册类型代码',
    type_name VARCHAR(100) NOT NULL COMMENT '注册类型名称',
    description VARCHAR(200) COMMENT '说明'
) COMMENT='企业登记注册类型字典';
